package terabox

import (
	"errors"
	"mime"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"
)

// AndroidShareClickObservation is one browser request actually observed through
// DevTools or a WebView capture. URL, body and headers are private wire inputs;
// no token, cookie, identity or click is generated by this adapter.
type AndroidShareClickObservation struct {
	Method     string            `json:"method"`
	URL        string            `json:"url"`
	Headers    map[string]string `json:"headers"`
	Body       string            `json:"body"`
	ObservedAt time.Time         `json:"observed_at"`
}

// ParseAndroidShareClickObservation imports a captured /api/srn/ck request as
// SDK inputs without HTTP or JavaScript execution. It does not establish the
// request's server result, a Play install, or acquisition credit. In particular,
// a request already sent by the browser must not be silently replayed.
func ParseAndroidShareClickObservation(deviceID string, observation AndroidShareClickObservation) (*AndroidClickAttribution, error) {
	invalid := func() (*AndroidClickAttribution, error) {
		return nil, errors.New("invalid Android share click observation")
	}
	if strings.TrimSpace(deviceID) == "" || !attributionStringValid(deviceID) || observation.Method != http.MethodPost ||
		observation.ObservedAt.IsZero() || observation.ObservedAt.Unix() <= 0 || len(observation.URL) > 1<<20 ||
		len(observation.Body) == 0 || len(observation.Body) > 1<<20 || len(observation.Headers) == 0 {
		return invalid()
	}
	endpoint, err := url.Parse(observation.URL)
	if err != nil || !observedShareHTTPSURL(endpoint) || endpoint.Path != "/api/srn/ck" || endpoint.RawPath != "" || endpoint.Fragment != "" {
		return invalid()
	}
	headers := make(map[string]string, len(observation.Headers))
	for key, value := range observation.Headers {
		identity := strings.ToLower(key)
		if identity == "" || strings.TrimSpace(key) != key || !attributionStringValid(key) || !attributionStringValid(value) || len(value) > 1<<20 {
			return invalid()
		}
		if _, exists := headers[identity]; exists {
			return invalid()
		}
		headers[identity] = value
	}
	contentType, _, err := mime.ParseMediaType(headers["content-type"])
	if err != nil || contentType != "application/x-www-form-urlencoded" || strings.TrimSpace(headers["user-agent"]) == "" {
		return invalid()
	}
	query, err := observedSingleValues(endpoint.RawQuery)
	if err != nil {
		return invalid()
	}
	form, err := observedSingleValues(observation.Body)
	if err != nil {
		return invalid()
	}
	allowed := map[string]bool{"pid": true, "c": true, "pdetail": true, "tera_link_id": true, "tera_link_type": true,
		"lang": true, "os_version": true, "device": true, "af_dp": true, "referrer": true, "agency": true, "op_source": true,
		"version": true, "devuid": true, "cuid": true}
	for key := range form {
		if !allowed[key] {
			return invalid()
		}
	}
	for _, key := range []string{"pid", "c", "pdetail", "tera_link_id", "tera_link_type", "lang", "os_version", "device", "af_dp", "referrer"} {
		if _, exists := form[key]; !exists {
			return invalid()
		}
	}
	if form["pid"] != "tera_sharelink" || form["pdetail"] != "header_button" || form["lang"] == "" ||
		query["jsToken"] == "" || query["dp-logid"] == "" || query["lang"] == "" {
		return invalid()
	}
	page, err := url.Parse(form["c"])
	if err != nil || !observedShareHTTPSURL(page) || urlOrigin(page) != urlOrigin(endpoint) {
		return invalid()
	}
	referer, err := url.Parse(headers["referer"])
	if err != nil || !observedShareHTTPSURL(referer) || referer.Fragment != "" {
		return invalid()
	}
	pageWithoutFragment := *page
	pageWithoutFragment.Fragment, pageWithoutFragment.RawFragment = "", ""
	if referer.String() != pageWithoutFragment.String() {
		return invalid()
	}
	if origin, exists := headers["origin"]; exists && origin != urlOrigin(page) {
		return invalid()
	}
	linkType, err := strconv.Atoi(form["tera_link_type"])
	if err != nil || linkType <= 0 {
		return invalid()
	}
	click := &AndroidClickAttribution{PageURL: form["c"], UserAgent: headers["user-agent"], DeepLink: form["af_dp"], TeraLinkID: form["tera_link_id"],
		TeraLinkType: linkType, Language: form["lang"], OSVersion: form["os_version"], Device: form["device"], Referrer: form["referrer"],
		CommonParams: query, BrowserCookies: headers["cookie"]}
	if value, exists := form["agency"]; exists {
		copy := value
		click.Agency = &copy
	}
	if value, exists := form["op_source"]; exists {
		copy := value
		click.OpSource = &copy
	}
	for _, key := range []string{"version", "devuid", "cuid"} {
		if value, exists := form[key]; exists {
			if click.BridgeBody == nil {
				click.BridgeBody = map[string]string{}
			}
			click.BridgeBody[key] = value
		}
	}
	if query["clienttype"] == "1" {
		if click.BridgeBody == nil {
			click.BridgeBody = map[string]string{}
		}
		click.BridgeBody["lang"] = click.Language
	}
	if validateAndroidClickCommonParams(click, deviceID) != nil ||
		validateAndroidAttributionCapture(AndroidAttributionCapture{DeviceID: deviceID, Click: click}, deviceID) != nil {
		return invalid()
	}
	return click, nil
}

func observedShareHTTPSURL(value *url.URL) bool {
	return value != nil && value.Scheme == "https" && value.User == nil && value.Opaque == "" && value.Port() == "" &&
		(value.Hostname() == TeraBoxDomain || strings.HasSuffix(value.Hostname(), "."+TeraBoxDomain))
}

func observedSingleValues(encoded string) (map[string]string, error) {
	values, err := url.ParseQuery(encoded)
	if err != nil {
		return nil, errors.New("invalid captured fields")
	}
	result := make(map[string]string, len(values))
	for key, items := range values {
		if key == "" || len(items) != 1 || !attributionStringValid(key) || !attributionStringValid(items[0]) {
			return nil, errors.New("ambiguous captured fields")
		}
		result[key] = items[0]
	}
	return result, nil
}
